    entry = @entries[key]
    return nil unless entry

    stored_payload = entry.payload
    packer ? packer.load(stored_payload) : stored_payload
  end

  def sweep
    @entries = @entries.reject { |_key, entry| entry.stale }
  end

private

  attr_reader :packer
end

